INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT133-S3-Q12$batch13$, 133, 3, 12, $batch13$Paradox$batch13$, $batch13$When adults toss balls to very young children they generally try to toss them as slowly as possible to compensate for the children's developing coordination. But recent studies show that despite their developing coordination, children actually have an easier time catching balls that are thrown at a faster speed.$batch13$, $batch13$Which one of the following, if true, most helps to explain why very young children find it easier to catch balls that are thrown at a faster speed?$batch13$, $batch13$A$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=133 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$Balls thrown at a faster speed, unlike balls thrown at a slower speed, trigger regions in the brain that control the tracking of objects for self-defense.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Balls that are tossed more slowly tend to have a higher arc that makes it less likely that the ball will be obscured by the body of the adult tossing it.$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$Adults generally find it easier to catch balls that are thrown slowly than balls that are thrown at a faster speed.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Children are able to toss balls back to the adults with more accuracy when they throw fast than when they throw the ball back more slowly.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$There is a limit to how fast the balls can be tossed to the children before the children start to have more difficulty in catching them.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$Young children, whose coordination is still developing, catch faster balls more easily than slow ones.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$You'd expect slow balls to be easier for children whose coordination is still developing. The answer needs something about fast balls that helps children catch them.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Find a feature of faster balls that makes them easier to catch.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Fast balls trigger brain regions that track objects for self-defense. That gives fast balls an advantage slow balls lack.$batch13$), ($batch13$B$batch13$, $batch13$This gives slow balls an advantage, which deepens the puzzle.$batch13$), ($batch13$C$batch13$, $batch13$The puzzle is about children, not adults.$batch13$), ($batch13$D$batch13$, $batch13$Throwing accuracy isn't catching.$batch13$), ($batch13$E$batch13$, $batch13$A speed limit doesn't explain why faster is easier below that limit.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT133-S3-Q12$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
